from pathlib import Path
import csv,json,statistics
R=Path(__file__).resolve().parents[1]
data=list(csv.DictReader((R/'resultados/comparativo.csv').open(encoding='utf-8-sig'),delimiter=';'))
series=[r for r in data if r['rodada'] in 'ABC' and r['rotas_ok']]
full=len(series)==9
med=[]
if full:
    for n in (1,2,3):med.append({'replicas':n,**{k:statistics.median(float(r[k]) for r in series if int(r['replicas'])==n) for k in ['sucessos_por_s','falhas_pct','p95_latencia_ok_ms','dropped_iterations_medicao']}})
cfg=json.loads((R/'resultados/calibracao.json').read_text(encoding='utf-8-sig')) if (R/'resultados/calibracao.json').exists() else {}
taxa=cfg.get('taxa','pendente')
eligible=[n for n in (1,2,3) if full and all(float(r['falhas_pct'])<1 and float(r['p95_latencia_ok_ms'])<800 and int(r['dropped_iterations_medicao'])==0 for r in series if int(r['replicas'])==n)]
decision=f'{min(eligible)} Pods cumprem as metas nas três repetições' if eligible else 'Nenhuma configuração cumpre todas as metas' if full else 'Decisão depende das nove medições'

slides=[
dict(title='RotaExpress',subtitle='Kubernetes na prática',kind='cover',body='Publicação, recuperação e escala de uma aplicação de rotas',source='Guia, p. 1',talk='Nosso trabalho investiga a operação de uma aplicação pronta. Publicamos o mesmo pacote no Kubernetes, verificamos a recuperação de falhas e comparamos quantas rotas são atendidas com uma, duas e três cópias. Os resultados representam este computador e esta demanda, não uma promessa universal de escalabilidade.',question='O que o grupo implementou?',answer='Infraestrutura declarativa, automação, evidências e experimento controlado. A aplicação original foi preservada.'),
dict(title='O problema da transportadora',kind='statement',body='Um cálculo por Pod de cada vez',detail='Pedidos simultâneos podem receber HTTP 503. O serviço busca a menor rota entre nove entregas fictícias.',source='Guia, p. 3. app.py original.',talk='A aplicação procura o menor circuito por força bruta. Com nove entregas, avalia 362.880 ordens. Cada processo tem um semáforo que permite um único cálculo. Se outro pedido chega enquanto está ocupado, ele recebe 503 imediatamente, sem fila. A interface desenha distâncias em linha reta entre pontos fictícios, sem trânsito ou ruas.',question='503 significa que o processo caiu?',answer='Não. Neste código, é uma recusa explícita porque o calculador está ocupado.'),
dict(title='Objetivos do experimento',kind='list',items=['Publicar a mesma imagem em um cluster local','Comprovar recriação de Pod e rollback','Comparar atendimento sob demanda constante','Escolher capacidade com base nas evidências'],source='Guia, pp. 1–3 e 28',talk='A pergunta central é o efeito do número de Pods sobre throughput, latência, falhas e recursos. Para responder, precisamos primeiro provar que a publicação funciona. Depois, mudamos somente réplicas e mantemos imagem, taxa, duração, recursos por Pod e script. O objetivo final é justificar uma decisão, inclusive reconhecer quando nenhuma configuração atende às metas.',question='Por que controlar as variáveis?',answer='Para atribuir diferenças observadas principalmente à quantidade de réplicas, reconhecendo ruído do host.'),
dict(title='Tecnologias e responsabilidades',kind='table',values=[['Tecnologia','Papel no laboratório'],['Docker','Imagem rotas:1.0 e nó do Minikube'],['Minikube e kubectl','Cluster local e administração da API'],['Python 3.12','Aplicação fornecida, sem bibliotecas externas'],['Grafana k6 1.0.0','Gerador de carga como Job no cluster']],source='Guia, pp. 4 e 8. Versões reais em documentacao/00.',talk='Docker empacota a aplicação e hospeda o nó. Minikube cria o cluster e configura o kubeconfig. kubectl envia pedidos à API Kubernetes. A aplicação usa Python 3.12 na imagem, embora o Python local usado para ferramentas seja 3.14. O k6 roda dentro do cluster, com versão fixa, para acessar o Service pelo caminho que distribui conexões.',question='Por que não instalar k6 no Windows?',answer='O guia exige execução interna e evita medir pelo port-forward, que escolhe um único Pod.'),
dict(title='Arquitetura do laboratório',kind='architecture',source='Guia, p. 2. Aula, pp. 29–32 e 42.',talk='O Deployment mantém os Pods identificados por app=rotas. O Service oferece o nome estável rotas e porta 8000. EndpointSlices listam os destinos prontos. O Job monta o JavaScript vindo do ConfigMap e envia requisições ao Service. Todos esses objetos ficam no namespace ops-lab. O terminal administra a API e o navegador acessa um túnel separado para demonstração.',question='O Service conhece o Pod menos ocupado?',answer='Não. A distribuição ocorre por conexão e não consulta o semáforo da aplicação.'),
dict(title='Ambiente e cluster',kind='numbers',numbers=[['3','CPUs limitadas no contêiner do nó'],['3072','MiB limitados no contêiner do nó'],['1','nó no perfil ops-lab']],detail='Windows 11, Ryzen 5 7600X, WSL 2 e Docker Desktop. O scheduler anuncia recursos da VM: veja o diagnóstico de capacidade.',source='resultados/logs/cluster-*.txt e evidencias/docker-node-hostconfig.json',talk='O host tem 12 processadores lógicos e cerca de 31 GB de RAM. O comando exigido limita o contêiner do Minikube a três CPUs e três GiB. Nesta versão, o kubelet informa ao scheduler a capacidade maior da VM, portanto quota do contêiner e capacidade anunciada não coincidem. Essa diferença é documentada e afeta a expectativa do exercício de seis réplicas. O nó ficou Ready e metrics-server foi habilitado.',question='3 CPUs significa três núcleos exclusivos?',answer='Não. É quota do contêiner Docker. O host e a VM continuam compartilhando recursos.'),
dict(title='A imagem Docker',kind='code',code='FROM python:3.12-slim\nCOPY app.py .\nUSER 10001:10001\nEXPOSE 8000\nCMD ["python", "app.py"]',detail='Build, testes HTTP fora do cluster e image load antes do Deployment',source='Dockerfile original. Guia, pp. 8–9.',talk='O Dockerfile define a base Python enxuta, copia somente a aplicação e usa usuário sem privilégios. EXPOSE é documentação da porta, não publicação. As variáveis de ambiente fazem logs imediatos e evitam gravação de bytecode. Primeiro construímos rotas:1.0, testamos os endpoints com Docker e encerramos o contêiner. Só então copiamos a imagem para o armazenamento separado do nó do Minikube.',question='Por que image load?',answer='A imagem do Docker do host não está automaticamente disponível no runtime do nó.'),
dict(title='Deployment, Pods e Service',kind='flow',labels=['Deployment','ReplicaSet','Pods'],detail='O controlador repõe o Pod excluído. O Service mantém um endereço estável para os destinos prontos.',source='Guia, pp. 10–16. evidencias/pod-antes-recriacao.json e pod-depois-recriacao.json',talk='Aplicamos primeiro o Deployment mínimo de uma réplica. Observamos a hierarquia e excluímos o Pod. O ReplicaSet criou outro com novo UID e endereço. Depois aplicamos a segunda versão com recursos, probes e segurança, gerando uma atualização gradual. O Service usa selector app=rotas, igual às labels do template. Ele resolve a instabilidade dos endereços individuais.',question='Um Pod criado sozinho seria reposto?',answer='Após exclusão, não. A reposição vem do controlador, aqui o ReplicaSet gerenciado pelo Deployment.'),
dict(title='Recursos e verificações de saúde',kind='table',values=[['Configuração por Pod','Valor e consequência'],['CPU request e limit','500m. Agendamento e teto de CPU'],['Memória request / limit','64Mi / 128Mi. QoS Burstable'],['Readiness','GET /readyz a cada 5 s'],['Liveness','GET /healthz a cada 10 s, após 10 s'],['Segurança','Não root, sem escalada, raiz somente leitura']],source='Guia, pp. 12–13 e 30. k8s/deployment.yaml.',talk='Request orienta onde cabe o Pod. Limit restringe execução. CPU acima do teto sofre throttling e memória além do limite pode encerrar o processo. Readiness controla se o Service encaminha novas conexões, enquanto liveness pode reiniciar o contêiner após falhas repetidas. Essas verificações não indicam que o calculador está livre: ele pode responder saúde e recusar cálculo por ocupação. A aplicação aceita a raiz somente leitura porque não grava dados.',question='Qual é a classe QoS?',answer='Burstable, pois request e limit de memória diferem.'),
dict(title='Falha controlada e rollback',kind='flow',labels=['rotas:1.1 ausente','Falha no rollout','undo para 1.0'],detail='O Pod antigo continua atendendo enquanto o novo não fica pronto',source='Guia, pp. 17–18. resultados/logs/rollback-*.txt.',talk='Alteramos a imagem para uma tag indisponível. O rollout expirou e os eventos mostraram falha de pull. Com uma réplica, a estratégia padrão arredonda maxUnavailable para zero e permite um Pod extra. Assim, o Pod anterior permaneceu pronto e respondeu ao teste interno. O rollout undo restaurou o template funcional. A comprovação inclui eventos, status e HTTP, não apenas o comando de undo.',question='O rollback desfaz banco de dados?',answer='Não. Ele restaura o template do Deployment e não reverte migrações ou estado externo.'),
dict(title='Metodologia de carga',kind='timeline',taxa=taxa,source='Guia, pp. 19–23. carga.js e resultados/calibracao.json.',talk=f'Executamos k6 como Job e acessamos http://rotas:8000. A taxa fixada na calibração é {taxa} pedidos por segundo. O aquecimento ocupa os primeiros dez segundos. A medição começa aos vinte e dura sessenta. O executor de chegadas constantes tenta manter a demanda independentemente da resposta. A cada requisição, abre conexão nova. p95 é só de sucessos e as metas são p95 abaixo de 800 ms, falhas abaixo de um por cento e nenhum descarte da medição.',question='Job Failed invalida a medição?',answer='Saída 99 com resumo completo indica thresholds não cumpridos e é resultado. Sem resumo é falha de execução.'),
dict(title='Comparação de 1, 2 e 3 Pods',kind='table',values=[['Rodada','1º teste','2º teste','3º teste'],['A','3 Pods','1 Pod','2 Pods'],['B','2 Pods','3 Pods','1 Pod'],['C','1 Pod','2 Pods','3 Pods']],detail=f'{len(series)}/9 medições completas. Mesma imagem, taxa, duração e recursos por Pod.',source='Guia, pp. 24–25. resultados/comparativo.csv.',talk='A ordem alternada reduz a chance de medir sempre a mesma configuração com o computador mais quente ou ocupado. Antes de cada teste, esperamos o Deployment e contamos endpoints prontos. Coletamos contadores antes e depois, logs completos e amostras de CPU e memória a cada quinze segundos. O throughput vem de rotas_ok dividido por sessenta. Os deltas dos Pods incluem o aquecimento e não precisam somar o total medido do k6.',question='Por que não usar o /s mostrado pelo k6?',answer='Ele divide pelo tempo total, incluindo períodos fora da janela própria de medição.'),
dict(title='Resultados das medições',kind='charts' if full else 'statement',body='Medições ainda pendentes' if not full else '',medians=med,detail='Mediana de três repetições por configuração. p95 somente dos sucessos.',source='resultados/comparativo.csv, medianas.csv e logs originais.',talk='Os gráficos apresentam apenas valores medidos. Cada coluna corresponde à mediana das três execuções da mesma configuração. Compare throughput e p95 junto com a taxa de falhas. p95 baixo, isoladamente, pode coexistir com muitas recusas. A mediana de três p95 é um resumo das execuções, e não o percentil calculado sobre todas as respostas reunidas.',question='A mediana prova significância estatística?',answer='Não. Com três repetições, a análise é descritiva e restrita ao ambiente.'),
dict(title='Diagnóstico e gargalos',kind='list',items=['Cálculo por força bruta e um trabalho por Pod','Service distribui conexões sem conhecer ocupação','Aplicação, k6 e control plane compartilham o nó','Quota Docker difere da capacidade anunciada'],source='app.py, amostras de recursos e evidencias/seis-replicas-*.',talk='A aplicação pode recusar uma conexão mesmo havendo outra réplica livre, pois o Service não consulta a ocupação. A meia CPU de cada Pod pode aumentar a duração do cálculo por throttling. O gerador também disputa recursos do nó. No exercício de seis réplicas, comparamos o comportamento observado à capacidade anunciada e à quota real. Saturação de CPU é inferida com apoio das amostras, que não são rastreamento contínuo. Fila, algoritmo ou balanceamento informado seriam investigações futuras.',question='Por que seis Pods podem rodar neste ambiente?',answer='O scheduler usa allocatable anunciado pela VM, maior que a quota Docker de três CPUs. Não se deve inventar Pending.'),
dict(title='Conclusão e decisão operacional',kind='statement',body=decision,detail='Custo reservado: 0,5 CPU por Pod. A decisão deve considerar falhas, p95, descartes e limites do nó.',source='documentacao/05-relatorio-experimentos.md e resultados/medianas.csv.',talk=decision+'. Escolhemos a menor configuração que cumpra as metas em todas as repetições; se nenhuma cumprir, registramos insuficiência neste cenário e investigamos o desenho da aplicação. Acrescentar réplicas aumenta CPU reservada e paralelismo, mas não garante escala linear. Todas as réplicas estão no mesmo nó, portanto nenhuma comparação demonstra proteção contra a queda do nó.',question='A maior taxa de sucesso sempre justifica mais Pods?',answer='É preciso avaliar metas e custo. Melhor throughput com falhas excessivas ainda pode ser inadequado.'),
dict(title='Demonstração do sistema',kind='demo',code='kubectl get deploy,pods,svc\nkubectl get endpointslices\nkubectl port-forward svc/rotas 8080:8000',detail='Interface, cálculo, logs, escala e evidências dos testes',source='documentacao/07-guia-demonstracao.md.',talk='Na demonstração, mostramos cluster e namespace, o Deployment, os Pods e o Service. Abrimos a interface, calculamos uma rota e identificamos quem atendeu. Em seguida mostramos logs, alteramos réplicas e conferimos endpoints. Terminamos com a tabela, os gráficos e os logs reais do k6. Se houver falha ao vivo, usamos evidências salvas e explicamos que representam a execução anterior. Depois encerramos o namespace e paramos o perfil conforme o guia.',question='Como reproduzir?',answer='A sequência de scripts e os comandos estão no documento 02 e no guia de demonstração. Os arquivos originais e evidências permanecem disponíveis.')]

objectives=['Delimitar o problema e o alcance do trabalho.','Relacionar concorrência aos HTTP 503 do protótipo.','Apresentar a pergunta e os controles do experimento.','Distinguir o papel de cada ferramenta.','Explicar o caminho da configuração e do tráfego.','Mostrar recursos reais e a diferença entre quota e capacidade anunciada.','Explicar como o pacote chega ao nó.','Demonstrar reconciliação e descoberta dos Pods.','Justificar limites, probes e segurança do manifesto.','Explicar a proteção da disponibilidade e a reversão.','Explicar o período medido e os thresholds.','Mostrar repetição e ordem alternada das configurações.','Comparar resultados sem ocultar falhas.','Separar observação de hipótese de gargalo.','Justificar a decisão para a demanda medida.','Guiar a demonstração com alternativa de evidências salvas.']
visuals=['A tipografia destaca o nome do projeto e o subtítulo delimita o tema.','A captura real mostra o circuito, a distância e o Pod. O texto ao lado explica por que uma requisição concorrente pode falhar.','As quatro linhas correspondem às entregas operacionais e experimentais.','A tabela associa cada tecnologia a uma responsabilidade específica, sem tratar Docker e Kubernetes como equivalentes.','As conexões mostram o ConfigMap entregando o script ao Job, o Job enviando tráfego ao Service e o Deployment mantendo os três Pods.','Os números grandes são limites do contêiner do nó, não CPUs exclusivas. A nota esclarece a capacidade anunciada pelo kubelet.','O trecho do Dockerfile é resumido para explicar base, fonte, usuário e processo. O arquivo original contém também WORKDIR e ENV.','A hierarquia mostra que Deployment mantém ReplicaSet e este mantém Pods. A descrição conecta isso à exclusão e reposição observadas.','As linhas da tabela separam agendamento, teto, prontidão, reinício e restrições de segurança.','As três etapas mostram a tag ausente, o rollout incompleto e o retorno à versão 1.0. O Pod antigo protege o serviço.','A tabela temporal separa aquecimento, intervalo e janela medida. A linha inferior fixa demanda e metas.','Leia as linhas A, B e C na horizontal. A alternância impede que uma configuração seja sempre a primeira.','O gráfico esquerdo mostra throughput em rotas/s. O direito mostra p95 em ms. As falhas medianas aparecem abaixo e precisam ser consideradas junto com as colunas.','As quatro linhas identificam mecanismos que podem limitar o sistema. Diferencie o que está no código do que foi comprovado por métricas.','A frase central expressa atendimento ou não das metas. O texto inferior explicita o custo de 0,5 CPU por Pod.','Os comandos mostram inspeção de objetos e o túnel local. Na demonstração, use também os comandos completos do guia 07.']
script='# Roteiro de apresentação\n\nTempo sugerido: 16 a 20 minutos de fala, mais 5 a 7 minutos de demonstração. Fontes nas notas de cada slide.\n\n'
for i,s in enumerate(slides,1):
    nxt=slides[i]['title'] if i<len(slides) else 'perguntas do professor'
    notes=f"Objetivo: {objectives[i-1]}\nConceitos: {s.get('detail',s.get('body',s['title']))}\nFala sugerida: {s['talk']}\nElementos visuais: {visuals[i-1]}\nTempo: {'45' if i==1 else '75'} segundos.\nTransição: a seguir, {nxt.lower()}.\nPergunta possível: {s['question']}\nResposta: {s['answer']}\nFonte: {s['source']}"
    s['notes']=notes
    script+=f"## Slide {i}: {s['title']}\n\n"+notes.replace('\n','\n\n')+'\n\n'
(R/'.build-apresentacao/slides.json').write_text(json.dumps(slides,indent=2,ensure_ascii=False),encoding='utf-8')
for p in ['apresentacao/roteiro-slides.md','documentacao/08-roteiro-apresentacao.md']:(R/p).write_text(script,encoding='utf-8')
print('Roteiro preparado com',len(slides),'slides')
